let route = { view: 'today', id: '' }, mode = 'list', statusFilter = 'open', projectFilter = '', query = '', weekOffset = 0, selectedDay = D.dateKey(), editing = null, undoAction = null, toastTimer, saveTimer;
function toast(message, undo) { clearTimeout(toastTimer); undoAction = undo || null; $('#toast span').textContent = message; $('#toast button').hidden = !undo; $('#toast').hidden = false; toastTimer = setTimeout(() => $('#toast').hidden = true, undo ? 10000 : 4500) }
function save() { if (loadError) { toast(loadError); return false } try { localStorage.setItem(KEY, JSON.stringify(state)); $('#save-status').textContent = 'Salvo localmente'; return true } catch { $('#save-status').textContent = 'Falha ao salvar'; toast('Não foi possível salvar. Exporte seu espaço para preservar as alterações.'); return false } }
