function project(id) { return state.projects.find(p => p.id === id) } function page(id) { return state.pages.find(p => p.id === id) }
function projectLabel(id) { const p = project(id); return p ? `<span class="project-label"><i class="color-dot ${p.color}"></i>${esc(p.title)}</span>` : '' }
function dateLabel(d) { if (!d) return 'Sem prazo'; if (d === D.dateKey()) return 'Hoje'; const tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1); if (d === D.dateKey(tomorrow)) return 'Amanhã'; return new Date(d + 'T12:00:00').toLocaleDateString('pt-BR', { day: 'numeric', month: 'short' }) }
const statuses = { todo: 'A fazer', doing: 'Em andamento', done: 'Concluída' }, navigation = [['today', 'sun', 'Hoje'], ['all', 'list', 'Tarefas'], ['week', 'calendar', 'Semana'], ['projects', 'folder', 'Projetos'], ['pages', 'book', 'Páginas'], ['inbox', 'inbox', 'Caixa de entrada']];
function navigate(view, id = '') { save(); location.hash = view + (id ? '/' + encodeURIComponent(id) : ''); $('#sidebar').classList.remove('open'); $('#mobile-menu').setAttribute('aria-expanded', 'false') }
function readRoute() { const [v, id] = location.hash.slice(1).split('/'); let decoded = ''; try { decoded = id ? decodeURIComponent(id) : '' } catch { } route = { view: navigation.some(x => x[0] === v) || ['project', 'page'].includes(v) ? v : 'today', id: decoded }; query = ''; projectFilter = ''; render(); window.scrollTo(0, 0) }
