function filteredTasks(tasks) { return tasks.filter(t => !projectFilter || t.projectId === projectFilter).filter(t => !query || (t.title + ' ' + t.notes + ' ' + (project(t.projectId)?.title || '')).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))).sort((a, b) => Number(b.pinned) - Number(a.pinned) || (a.date || '9999').localeCompare(b.date || '9999') || Number(b.priority === 'high') - Number(a.priority === 'high')) }
function taskRow(t) { return `<div class="task-row ${t.done ? 'done' : ''}"><input type="checkbox" aria-label="${t.done ? 'Reabrir' : 'Concluir'} ${esc(t.title)}" data-action="toggle-task" data-id="${esc(t.id)}" ${t.done ? 'checked' : ''}><button class="task-name" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}${t.notes ? '<span class="note-indicator">' + icon('file') + '</span>' : ''}</button><div class="task-project">${projectLabel(t.projectId)}</div><span class="task-date ${!t.done && t.date && t.date < D.dateKey() ? 'overdue' : ''}">${dateLabel(t.date)}</span><span class="priority-mark ${t.priority === 'high' ? 'high' : ''}" title="${t.priority === 'high' ? 'Alta prioridade' : 'Prioridade normal'}">${t.priority === 'high' ? '↑' : '−'}</span><button class="icon-button pin-button ${t.pinned ? 'pinned' : ''}" aria-label="${t.pinned ? 'Desafixar' : 'Fixar'} tarefa" data-action="pin-task" data-id="${esc(t.id)}">${icon('pin')}</button><button class="icon-button" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Editar ${esc(t.title)}">${icon('more')}</button></div>` }
