function board(tasks) { return `<div class="board">${Object.entries(statuses).map(([s, label]) => `<section class="board-column" data-drop-status="${s}"><div class="column-heading"><i class="status-dot ${s}"></i><h3>${label}</h3><span>${tasks.filter(t => t.status === s).length}</span><button class="icon-button" aria-label="Adicionar em ${label}" data-action="new-task" data-status="${s}">${icon('plus')}</button></div>${tasks.filter(t => t.status === s).map(t => `<article class="kanban-card" draggable="true" data-drag-task="${esc(t.id)}"><div class="card-top">${projectLabel(t.projectId)}<button class="icon-button" aria-label="Editar ${esc(t.title)}" data-action="edit-task" data-id="${esc(t.id)}">${icon('more')}</button></div><button class="kanban-title" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button>${t.notes ? `<p>${esc(t.notes.slice(0, 90))}</p>` : ''}<div class="card-bottom"><span class="${t.date && t.date < D.dateKey() && !t.done ? 'overdue' : ''}">${icon('calendar')}${dateLabel(t.date)}</span>${t.priority === 'high' ? '<span class="priority-chip">Alta</span>' : ''}</div><select aria-label="Status de ${esc(t.title)}" data-change="status" data-id="${esc(t.id)}">${Object.entries(statuses).map(([k, v]) => `<option value="${k}" ${t.status === k ? 'selected' : ''}>${v}</option>`).join('')}</select></article>`).join('') || '<p class="column-empty">Espaço para o próximo passo.</p>'}</section>`).join('')}</div>` }
