function todayView() { const today = D.dateKey(), tasks = filteredTasks(state.tasks.filter(t => !t.done && ((t.date && t.date <= today) || t.pinned))), done = state.tasks.filter(t => t.done && t.completedAt && D.dateKey(new Date(t.completedAt)) === today).length; return `<section class="today-hero"><div><p class="overline">${new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })}</p><h1>Um dia de cada vez<span class="blue-period">.</span></h1><p class="lead">Um lugar para o que você precisa fazer. E para o que quer criar.</p><div class="hero-actions">${btn('Nova tarefa', 'new-task', 'primary', 'plus')}<button class="text-button" data-action="nav" data-view="week">Planejar a semana ${icon('arrow')}</button></div></div><div class="day-art" aria-hidden="true"><div class="art-caption">O ESPAÇO É SEU</div><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="orb orb-three"></div><div class="art-line"></div><div class="art-foot">menos ruído, mais intenção.</div></div></section><div class="week-ribbon">${D.weekDates().map(d => `<button data-action="open-day" data-date="${d}" class="${d === today ? 'current' : ''}"><span>${new Date(d + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'short' }).replace('.', '')}</span><strong>${Number(d.slice(-2))}</strong><i class="${state.tasks.some(t => t.date === d && !t.done) ? 'has-tasks' : ''}"></i></button>`).join('')}<div class="week-summary"><span>HOJE</span><strong>${tasks.length} em aberto <i>·</i> ${done} concluída${done === 1 ? '' : 's'}</strong></div></div><div class="home-columns"><section class="home-main"><div class="section-heading"><h2>Na sua mesa <span class="count">${tasks.length}</span></h2><button class="text-button" data-action="nav" data-view="all">Ver todas ${icon('arrow')}</button></div>${tasks.length ? taskList(tasks) : empty('Sua mesa está livre.', 'Adicione tarefas para hoje ou fixe o que merece atenção.', 'new-task', 'Adicionar tarefa')}<div class="section-heading project-heading"><h2>Projetos em movimento</h2><button class="text-button" data-action="nav" data-view="projects">Abrir projetos ${icon('arrow')}</button></div><div class="project-grid home-projects">${state.projects.filter(p => !p.archived).slice(0, 3).map(projectCard).join('') || `<button class="project-new" data-action="new-project">${icon('plus')}<span>Comece um projeto</span><small>Reúna tarefas e notas em um só lugar.</small></button>`}</div></section><aside class="home-side"><section class="daily-note"><div class="section-heading"><h2>Intenção do dia</h2>${icon('sun')}</div><p>O que faria hoje valer a pena?</p><textarea id="daily-note" aria-label="Intenção do dia" maxlength="5000" placeholder="Hoje, quero abrir espaço para…">${esc(state.daily[today] || '')}</textarea><span class="small muted">Só para você. Salvo automaticamente.</span></section><section class="quick-note"><div class="section-heading"><h2>Rascunho</h2>${icon('file')}</div><p>Uma ideia, um lembrete, qualquer coisa.</p><textarea id="scratch" aria-label="Rascunho" maxlength="20000" placeholder="Tire da cabeça. Organize depois.">${esc(state.scratch)}</textarea><div class="scratch-actions"><button class="text-button" data-action="scratch-task">Virar tarefa ${icon('arrow')}</button><button class="text-button" data-action="scratch-page">Virar página ${icon('arrow')}</button></div></section><button class="notebook-link" data-action="nav" data-view="pages">${icon('book')}<div>Seu caderno<small>${state.pages.length} página${state.pages.length === 1 ? '' : 's'} para guardar ideias</small></div>${icon('arrow')}</button></aside></div>` }
function projectCard(p) { const tasks = state.tasks.filter(t => t.projectId === p.id), done = tasks.filter(t => t.done).length, percentage = tasks.length ? Math.round(done / tasks.length * 100) : 0; return `<button class="project-card ${p.color}" data-action="nav" data-view="project" data-id="${esc(p.id)}"><span class="project-symbol">${icon('folder')}</span><span class="project-title">${esc(p.title)}</span><span class="project-description">${esc(p.description || 'Um espaço para reunir seus próximos passos.')}</span><span class="project-progress"><span>${done}/${tasks.length} tarefas</span><span>${percentage}%</span></span><span class="progress-track"><i style="width:${percentage}%"></i></span></button>` }
function projectsView() { return titleBlock('DO PLANO À PRÁTICA', 'Projetos', 'Cada projeto, com suas tarefas, páginas e próximos passos.', btn('Novo projeto', 'new-project', 'primary', 'plus')) + `<div class="project-grid">${state.projects.filter(p => !p.archived).map(projectCard).join('')}<button class="project-new" data-action="new-project">${icon('plus')}<span>Um novo começo</span><small>Crie um projeto pessoal ou de trabalho.</small></button></div>${state.projects.some(p => p.archived) ? `<div class="section-heading"><h2>Arquivados</h2></div><div class="project-grid">${state.projects.filter(p => p.archived).map(projectCard).join('')}</div>` : ''}` }
function projectView() { const p = project(route.id); if (!p) return empty('Projeto não encontrado.', 'Escolha outro projeto.', 'nav-projects', 'Ver projetos'); return titleBlock('PROJETO' + (p.archived ? ' · ARQUIVADO' : ''), p.title, esc(p.description || 'Suas tarefas e referências, juntas.'), `<button class="button secondary" data-action="edit-project" data-id="${esc(p.id)}">Editar projeto</button>${btn('Nova tarefa', 'new-task', 'primary', 'plus')}`) + `<div class="project-detail-summary"><span class="color-dot ${p.color}"></span><strong>${state.tasks.filter(t => t.projectId === p.id && !t.done).length} tarefas em aberto</strong><span>${state.tasks.filter(t => t.projectId === p.id && t.done).length} concluídas</span></div>` + taskSection(state.tasks.filter(t => t.projectId === p.id)) + `<div class="section-heading project-heading"><h2>Páginas do projeto</h2>${btn('Nova página', 'new-page', 'secondary', 'plus')}</div><div class="pages-grid">${state.pages.filter(x => x.projectId === p.id).map(pageCard).join('') || '<p class="muted">Guarde decisões, ideias e referências em uma página deste projeto.</p>'}</div>` }
function weekView() { const dates = D.weekDates(weekOffset), today = D.dateKey(); return titleBlock('VISÃO DA SEMANA', 'Faça espaço na agenda.', 'Distribua as tarefas nos dias. Arraste ou altere o prazo ao editar.', btn('Nova tarefa', 'new-task', 'primary', 'plus')) + `<div class="week-controls"><div><button class="icon-button" data-action="week-prev" aria-label="Semana anterior">${icon('left')}</button><strong>${dateLabel(dates[0])} — ${dateLabel(dates[6])}</strong><button class="icon-button" data-action="week-next" aria-label="Próxima semana">${icon('chevron')}</button></div><button class="button secondary" data-action="week-current">Esta semana</button></div><div class="week-board">${dates.map(d => `<section class="day-column ${d === today ? 'current' : ''} ${d === selectedDay ? 'selected-day' : ''}" data-drop-date="${d}"><div class="day-heading"><span>${new Date(d + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'short' })}</span><strong>${Number(d.slice(-2))}</strong></div>${state.tasks.filter(t => t.date === d).map(t => `<article class="week-task ${t.done ? 'done' : ''}" draggable="true" data-drag-task="${esc(t.id)}"><button data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button>${projectLabel(t.projectId)}<span class="small muted">${statuses[t.status]}</span></article>`).join('')}<button class="day-add" data-action="new-task" data-date="${d}" aria-label="Adicionar tarefa em ${dateLabel(d)}">${icon('plus')} Adicionar</button></section>`).join('')}</div><div class="section-heading project-heading"><h2>Sem data definida</h2><span class="small muted">Arraste para um dia ou abra para definir o prazo.</span></div><div class="unscheduled">${state.tasks.filter(t => !t.date && !t.done).map(t => `<article class="week-task" draggable="true" data-drag-task="${esc(t.id)}"><button data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button>${projectLabel(t.projectId)}</article>`).join('') || '<p class="muted">Nenhuma tarefa sem prazo.</p>'}</div>` }
