function pagesView() { return titleBlock('IDEIAS QUE FICAM', 'Seu caderno', 'Páginas livres para anotar, pensar e organizar. Conectadas aos seus projetos.', btn('Nova página', 'new-page', 'primary', 'plus')) + `<div class="page-template-banner"><div>${icon('book')}<span><strong>Uma página para começar melhor.</strong><small>Use um roteiro de planejamento semanal ou comece do zero.</small></span></div><button class="button secondary" data-action="template-page">Usar roteiro semanal ${icon('arrow')}</button></div><div class="pages-grid">${[...state.pages].sort((a, b) => Number(b.favorite) - Number(a.favorite)).map(pageCard).join('') || empty('Seu próximo pensamento cabe aqui.', 'Crie uma página com textos, títulos, listas e checklists.', 'new-page', 'Criar página')}</div>` }
const blockNames = { text: 'Texto', heading: 'Título', check: 'Checklist', quote: 'Citação', divider: 'Divisor' };
function blockView(b, index) { return `<div class="editor-block ${b.type}"><div class="block-tools"><button class="icon-button" data-action="block-up" data-id="${esc(b.id)}" aria-label="Mover bloco ${index + 1} para cima" ${index === 0 ? 'disabled' : ''}>${icon('up')}</button><button class="icon-button" data-action="block-down" data-id="${esc(b.id)}" aria-label="Mover bloco ${index + 1} para baixo">${icon('down')}</button><button class="icon-button" data-action="block-delete" data-id="${esc(b.id)}" aria-label="Excluir bloco ${index + 1}">${icon('x')}</button></div>${b.type === 'check' ? `<input type="checkbox" data-block-check="${esc(b.id)}" aria-label="Marcar item ${index + 1}" ${b.checked ? 'checked' : ''}>` : ''}${b.type === 'divider' ? '<hr>' : `<textarea class="block-input ${b.checked ? 'checked' : ''}" data-block-input="${esc(b.id)}" aria-label="${blockNames[b.type]} do bloco ${index + 1}" placeholder="${b.type === 'heading' ? 'Título da seção' : b.type === 'check' ? 'Um item para lembrar' : 'Escreva aqui…'}" maxlength="20000" rows="1">${esc(b.text)}</textarea>`}</div>` }
function pageView() { const p = page(route.id); if (!p) return empty('Página não encontrada.', 'Escolha outra página no seu caderno.', 'nav-pages', 'Abrir páginas'); return `<div class="document-top"><button class="text-button" data-action="nav" data-view="pages">${icon('left')} Seu caderno</button><div><button class="button secondary ${p.favorite ? 'favorite' : ''}" data-action="favorite-page" data-id="${esc(p.id)}">${icon('star')}${p.favorite ? 'Favorita' : 'Favoritar'}</button><button class="icon-button" aria-label="Editar detalhes da página" data-action="edit-page" data-id="${esc(p.id)}">${icon('more')}</button></div></div><div class="document"><div class="document-icon">${icon('file')}</div><input id="page-title" class="document-title" aria-label="Título da página" value="${esc(p.title)}" maxlength="200"><div class="document-meta">${projectLabel(p.projectId) || '<span>Página pessoal</span>'}<span>·</span><span>Salvamento automático</span></div><div id="blocks">${p.blocks.map(blockView).join('')}</div><div class="block-add"><span>Adicionar bloco</span>${Object.entries(blockNames).map(([k, v]) => `<button data-action="block-add" data-type="${k}">${k === 'check' ? icon('check') : k === 'heading' ? '<b>H</b>' : k === 'divider' ? '<b>—</b>' : icon('file')}${v}</button>`).join('')}</div><p class="document-help">Textos e checklists para organizar suas ideias. Reordene os blocos com as setas.</p></div>` }
function inboxView() { return titleBlock('CAPTURAR AGORA, ORGANIZAR DEPOIS', 'Caixa de entrada', 'Tarefas sem projeto ou prazo ficam aqui até você decidir o próximo passo.', btn('Capturar tarefa', 'capture-task', 'primary', 'plus')) + taskList(filteredTasks(state.tasks.filter(t => !t.done && !t.date && !t.projectId))) }
function render() { renderNav(); const labels = { today: 'Hoje', all: 'Tarefas', week: 'Semana', projects: 'Projetos', project: project(route.id)?.title || 'Projeto', pages: 'Páginas', page: page(route.id)?.title || 'Página', inbox: 'Caixa de entrada' }; $('#breadcrumb').textContent = labels[route.view]; document.title = `${labels[route.view]} · clarity.ai`; $('#view').className = 'view ' + route.view; const views = { today: todayView, all: () => titleBlock('UM PASSO DE CADA VEZ', 'Suas tarefas', 'Veja o que está em aberto, acompanhe o andamento e encontre o próximo passo.', btn('Nova tarefa', 'new-task', 'primary', 'plus')) + taskSection(state.tasks), week: weekView, projects: projectsView, project: projectView, pages: pagesView, page: pageView, inbox: inboxView }; $('#view').innerHTML = views[route.view](); icons(); resizeBlocks() }
function resizeBlocks() { document.querySelectorAll('.block-input').forEach(e => { e.style.height = 'auto'; e.style.height = e.scrollHeight + 'px' }) }
function projectOptions(selected) { return `<option value="">Sem projeto</option>${state.projects.filter(p => !p.archived || p.id === selected).map(p => `<option value="${esc(p.id)}" ${p.id === selected ? 'selected' : ''}>${esc(p.title)}</option>`).join('')}` }
function openEntity(kind, entity = null, defaults = {}) { editing = { kind, id: entity?.id || '', defaults }; const isTask = kind === 'task', isProject = kind === 'project'; $('#entity-kind').textContent = isTask ? 'TAREFA' : isProject ? 'PROJETO' : 'PÁGINA'; $('#entity-title').textContent = (entity ? 'Editar ' : isTask || kind === 'page' ? 'Nova ' : 'Novo ') + (isTask ? 'tarefa' : isProject ? 'projeto' : 'página'); $('#entity-delete').hidden = !entity; let fields = `<label>${isTask ? 'O que precisa ser feito?' : 'Título'}<input name="title" required maxlength="200" value="${esc(entity?.title || defaults.title || '')}" placeholder="${isTask ? 'Ex.: revisar a proposta' : isProject ? 'Ex.: reforma do escritório' : 'Ex.: ideias para o próximo mês'}"></label>`; if (isTask) { fields += `<label>Notas <span class="optional">opcional</span><textarea name="notes" rows="3" maxlength="2000">${esc(entity?.notes || defaults.notes || '')}</textarea></label><div class="form-row"><label>Prazo<input name="date" type="date" value="${esc(entity?.date ?? defaults.date ?? D.dateKey())}"></label><label>Prioridade<select name="priority"><option value="normal">Normal</option><option value="high" ${entity?.priority === 'high' ? 'selected' : ''}>Alta</option></select></label></div><div class="form-row"><label>Projeto<select name="projectId">${projectOptions(entity?.projectId ?? defaults.projectId ?? (route.view === 'project' ? route.id : ''))}</select></label><label>Status<select name="status">${Object.entries(statuses).map(([k, v]) => `<option value="${k}" ${(entity?.status || defaults.status || 'todo') === k ? 'selected' : ''}>${v}</option>`).join('')}</select></label></div><label class="checkbox-label"><input name="pinned" type="checkbox" ${entity?.pinned ? 'checked' : ''}>Fixar na minha mesa</label>` } else if (isProject) { fields += `<label>Descrição <span class="optional">opcional</span><textarea name="description" rows="3" maxlength="2000">${esc(entity?.description || '')}</textarea></label><label>Cor do projeto<select name="color">${[['blue', 'Azul'], ['green', 'Verde'], ['orange', 'Terracota'], ['rose', 'Rosa'], ['purple', 'Lavanda']].map(([k, v]) => `<option value="${k}" ${entity?.color === k ? 'selected' : ''}>${v}</option>`).join('')}</select></label>${entity ? `<label class="checkbox-label"><input type="checkbox" name="archived" ${entity.archived ? 'checked' : ''}>Arquivar projeto</label>` : ''}` } else { fields += `<label>Projeto<select name="projectId">${projectOptions(entity?.projectId ?? (route.view === 'project' ? route.id : ''))}</select></label><label class="checkbox-label"><input name="favorite" type="checkbox" ${entity?.favorite ? 'checked' : ''}>Favoritar na barra lateral</label>` } $('#entity-fields').innerHTML = fields; $('#entity-dialog').showModal(); $('#entity-form').elements.title.focus() }
function setTaskStatus(t, status) { t.status = status; t.done = status === 'done'; t.completedAt = t.done ? (t.completedAt || new Date().toISOString()) : null }
$('#entity-form').onsubmit = e => { e.preventDefault(); const v = e.currentTarget.elements, title = v.title.value.trim(); if (!title) { v.title.setCustomValidity('Escreva um título.'); v.title.reportValidity(); return } const { kind, id, defaults } = editing; let entity; const now = new Date().toISOString(); if (kind === 'task') { entity = state.tasks.find(t => t.id === id) || { id: D.id(), createdAt: now }; const wasDone = entity.done; Object.assign(entity, { title, notes: v.notes.value.trim(), date: v.date.value, priority: v.priority.value, projectId: v.projectId.value, pinned: v.pinned.checked }); setTaskStatus(entity, v.status.value); if (entity.done && !wasDone) entity.completedAt = now; if (!id) state.tasks.push(entity) } else if (kind === 'project') { entity = state.projects.find(p => p.id === id) || { id: D.id() }; Object.assign(entity, { title, description: v.description.value.trim(), color: v.color.value, archived: !!v.archived?.checked }); if (!id) state.projects.push(entity) } else { entity = state.pages.find(p => p.id === id) || { id: D.id(), blocks: defaults.blocks || [{ id: D.id(), type: 'text', text: '' }] }; Object.assign(entity, { title, projectId: v.projectId.value, favorite: v.favorite.checked, updatedAt: now }); if (!id) state.pages.push(entity) } $('#entity-dialog').close(); commit(id ? 'Alterações salvas.' : kind === 'task' ? 'Tarefa criada.' : kind === 'project' ? 'Projeto criado.' : 'Página criada.'); if (kind === 'page' && !id) navigate('page', entity.id) };
$('#entity-form').addEventListener('input', e => { if (e.target.name === 'title') e.target.setCustomValidity('') });
$('#entity-delete').onclick = () => { const { kind, id } = editing, list = kind === 'task' ? state.tasks : kind === 'project' ? state.projects : state.pages, index = list.findIndex(x => x.id === id); if (index < 0) return; const removed = list.splice(index, 1)[0], taskLinks = [], pageLinks = []; if (kind === 'project') { state.tasks.filter(t => t.projectId === id).forEach(t => { taskLinks.push(t.id); t.projectId = '' }); state.pages.filter(p => p.projectId === id).forEach(p => { pageLinks.push(p.id); p.projectId = '' }) } $('#entity-dialog').close(); if (route.id === id) navigate(kind === 'page' ? 'pages' : kind === 'project' ? 'projects' : 'all'); commit('Excluído. ' + (kind === 'project' ? 'Tarefas e páginas foram preservadas.' : ''), () => { list.splice(index, 0, removed); taskLinks.forEach(i => { const t = state.tasks.find(t => t.id === i); if (t) t.projectId = id }); pageLinks.forEach(i => { const p = page(i); if (p) p.projectId = id }); commit('Restaurado.') }) };
function updateTaskResults() { const source = route.view === 'project' ? state.tasks.filter(t => t.projectId === route.id) : state.tasks, list = filteredTasks(source.filter(t => statusFilter === 'all' || (statusFilter === 'done' ? t.done : !t.done))); $('#task-results').innerHTML = mode === 'board' ? board(list) : taskList(list) }
document.addEventListener('click', e => { const close = e.target.closest('[data-close]'); if (close) { close.closest('dialog').close(); return } const b = e.target.closest('[data-action]'); if (!b) return; const a = b.dataset.action, id = b.dataset.id, t = state.tasks.find(t => t.id === id), p = page(route.id); if (a === 'nav') { projectFilter = ''; navigate(b.dataset.view, id) } else if (a === 'nav-projects') navigate('projects'); else if (a === 'nav-pages') navigate('pages'); else if (a === 'new-task' || a === 'capture-task') openEntity('task', null, { date: a === 'capture-task' ? '' : b.dataset.date, status: b.dataset.status }); else if (a === 'edit-task' && t) openEntity('task', t); else if (a === 'pin-task' && t) { t.pinned = !t.pinned; commit(t.pinned ? 'Tarefa fixada na sua mesa.' : 'Tarefa desafixada.') } else if (a === 'new-project') openEntity('project'); else if (a === 'edit-project') openEntity('project', project(id)); else if (a === 'new-page') openEntity('page'); else if (a === 'edit-page') openEntity('page', page(id)); else if (a === 'favorite-page') { const pg = page(id); if (pg) { pg.favorite = !pg.favorite; commit() } } else if (a === 'set-mode') { mode = b.dataset.mode; if (mode === 'board') statusFilter = 'all'; render() } else if (a === 'week-prev') { weekOffset--; render() } else if (a === 'week-next') { weekOffset++; render() } else if (a === 'week-current') { weekOffset = 0; selectedDay = D.dateKey(); render() } else if (a === 'open-day') { selectedDay = b.dataset.date; weekOffset = 0; navigate('week') } else if (a === 'scratch-task') { if (!state.scratch.trim()) { toast('Escreva uma ideia no rascunho primeiro.'); return } openEntity('task', null, { title: state.scratch.trim().split('\n')[0].slice(0, 200), notes: state.scratch.slice(0, 2000), date: '' }) } else if (a === 'scratch-page') { if (!state.scratch.trim()) { toast('Escreva uma ideia no rascunho primeiro.'); return } openEntity('page', null, { title: state.scratch.trim().split('\n')[0].slice(0, 200), blocks: [{ id: D.id(), type: 'text', text: state.scratch }] }) } else if (a === 'template-page') { const pg = { id: D.id(), title: 'Meu planejamento semanal', projectId: '', favorite: false, updatedAt: new Date().toISOString(), blocks: [['heading', 'O que importa nesta semana?'], ['text', ''], ['heading', 'Três prioridades'], ['check', ''], ['check', ''], ['check', ''], ['heading', 'Compromissos e espaço livre'], ['text', ''], ['heading', 'Revisão da semana'], ['quote', 'O que funcionou? O que quero ajustar?']].map(([type, text]) => ({ id: D.id(), type, text, checked: false })) }; state.pages.push(pg); save(); navigate('page', pg.id) } else if (a === 'block-add' && p) { const block = { id: D.id(), type: b.dataset.type, text: '', checked: false }; p.blocks.push(block); p.updatedAt = new Date().toISOString(); save(); render();[...document.querySelectorAll('[data-block-input]')].find(x => x.dataset.blockInput === block.id)?.focus() } else if (a.startsWith('block-') && p) { const index = p.blocks.findIndex(x => x.id === id); if (index < 0) return; p.updatedAt = new Date().toISOString(); if (a === 'block-delete') { const removed = p.blocks.splice(index, 1)[0]; commit('Bloco excluído.', () => { p.blocks.splice(index, 0, removed); commit('Bloco restaurado.') }) } else { const dest = a === 'block-up' ? index - 1 : index + 1; if (dest >= 0 && dest < p.blocks.length) { [p.blocks[index], p.blocks[dest]] = [p.blocks[dest], p.blocks[index]]; commit() } } } });
document.addEventListener('change', e => { const x = e.target; if (x.dataset.action === 'toggle-task') { const t = state.tasks.find(t => t.id === x.dataset.id); if (t) { setTaskStatus(t, x.checked ? 'done' : 'todo'); commit(t.done ? 'Tarefa concluída.' : 'Tarefa reaberta.') } } else if (x.dataset.change === 'status') { const t = state.tasks.find(t => t.id === x.dataset.id); if (t) { setTaskStatus(t, x.value); commit('Status atualizado.') } } else if (x.dataset.change === 'filter-status') { statusFilter = x.value; updateTaskResults() } else if (x.dataset.change === 'filter-project') { projectFilter = x.value; updateTaskResults() } else if (x.dataset.blockCheck) { const p = page(route.id), b = p?.blocks.find(b => b.id === x.dataset.blockCheck); if (b) { b.checked = x.checked; p.updatedAt = new Date().toISOString(); save(); x.closest('.editor-block').querySelector('textarea')?.classList.toggle('checked', b.checked) } } });
document.addEventListener('input', e => { const x = e.target; if (x.id === 'daily-note') { state.daily[D.dateKey()] = x.value; autosave() } else if (x.id === 'scratch') { state.scratch = x.value; autosave() } else if (x.id === 'task-search') { query = x.value; updateTaskResults() } else if (x.id === 'page-title') { const p = page(route.id); if (p) { p.title = x.value; p.updatedAt = new Date().toISOString(); $('#breadcrumb').textContent = x.value; renderNav(); autosave() } } else if (x.dataset.blockInput) { const p = page(route.id), b = p?.blocks.find(b => b.id === x.dataset.blockInput); if (b) { b.text = x.value; p.updatedAt = new Date().toISOString(); x.style.height = 'auto'; x.style.height = x.scrollHeight + 'px'; autosave() } } });
let dragged = ''; document.addEventListener('dragstart', e => { const card = e.target.closest('[data-drag-task]'); if (card) { dragged = card.dataset.dragTask; e.dataTransfer.setData('text/plain', dragged); e.dataTransfer.effectAllowed = 'move' } }); document.addEventListener('dragover', e => { const drop = e.target.closest('[data-drop-status],[data-drop-date]'); if (drop && dragged) { e.preventDefault(); drop.classList.add('drag-over') } }); document.addEventListener('dragleave', e => e.target.closest('[data-drop-status],[data-drop-date]')?.classList.remove('drag-over')); document.addEventListener('drop', e => { const drop = e.target.closest('[data-drop-status],[data-drop-date]'); if (!drop || !dragged) return; e.preventDefault(); const t = state.tasks.find(t => t.id === dragged); dragged = ''; if (t) { if (drop.dataset.dropStatus) setTaskStatus(t, drop.dataset.dropStatus); if (drop.dataset.dropDate) t.date = drop.dataset.dropDate; commit('Tarefa movida.') } }); document.addEventListener('dragend', () => { dragged = ''; document.querySelectorAll('.drag-over').forEach(e => e.classList.remove('drag-over')) });
function commandResults() { const q = $('#command-input').value.trim().toLocaleLowerCase('pt-BR'), matches = [...state.tasks.map(t => ({ type: 'Tarefa', icon: 'list', title: t.title, content: t.notes, id: t.id, view: 'task' })), ...state.projects.map(p => ({ type: 'Projeto', icon: 'folder', title: p.title, content: p.description, id: p.id, view: 'project' })), ...state.pages.map(p => ({ type: 'Página', icon: 'file', title: p.title, content: p.blocks.map(b => b.text).join(' '), id: p.id, view: 'page' }))].filter(x => (x.title + ' ' + x.content).toLocaleLowerCase('pt-BR').includes(q)).slice(0, 20); $('#command-results').innerHTML = (q ? '' : `<div class="command-group">CRIAR</div>${[['task', 'Nova tarefa', 'list'], ['project', 'Novo projeto', 'folder'], ['page', 'Nova página', 'file']].map(([k, t, i]) => `<button data-command-new="${k}">${icon(i)}<span>${t}</span>${icon('plus')}</button>`).join('')}`) + (matches.length ? `<div class="command-group">${q ? 'RESULTADOS' : 'NO SEU ESPAÇO'}</div>` + matches.map(x => `<button data-command-view="${x.view}" data-id="${esc(x.id)}">${icon(x.icon)}<span>${esc(x.title)}</span><small>${x.type}</small></button>`).join('') : q ? '<p class="command-empty">Nenhum resultado. Experimente outra palavra.</p>' : '') }
function openCommand() { commandResults(); $('#command-dialog').showModal(); $('#command-input').focus() }
$('#command-open').onclick = openCommand; $('#command-input').oninput = commandResults; $('#command-results').onclick = e => { const b = e.target.closest('button'); if (!b) return; $('#command-dialog').close(); if (b.dataset.commandNew) openEntity(b.dataset.commandNew); else if (b.dataset.commandView === 'task') openEntity('task', state.tasks.find(t => t.id === b.dataset.id)); else navigate(b.dataset.commandView, b.dataset.id) };
$('#quick-create').onclick = () => openEntity('task'); $('#sidebar-project-add').onclick = () => openEntity('project'); $('#settings-open').onclick = () => $('#settings-dialog').showModal(); $('#mobile-menu').onclick = () => { const open = $('#sidebar').classList.toggle('open'); $('#mobile-menu').setAttribute('aria-expanded', String(open)) }; $('#toast button').onclick = () => { const action = undoAction; undoAction = null; action?.() };
function download(name, data) { const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
$('#export').onclick = () => { download('clarity-ai-espaco-' + D.dateKey() + '.json', { ...state, exportedAt: new Date().toISOString() }); toast('Cópia do espaço exportada.') }; $('#import').onclick = () => $('#import-file').click(); $('#import-file').onchange = async e => { const file = e.target.files[0]; if (!file) return; try { if (file.size > 10 * 1024 * 1024) throw new Error('A cópia precisa ter menos de 10 MB.'); const incoming = D.normalize(JSON.parse(await file.text())), previous = structuredClone(state); state = D.merge(state, incoming); loadError = ''; commit('Cópia importada. Os registros existentes foram preservados.', () => { state = previous; commit('Importação desfeita.') }); $('#settings-dialog').close() } catch (error) { toast(error.message || 'Não foi possível importar.') } e.target.value = '' };
document.addEventListener('keydown', e => { const typing = ['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName); if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); if (!$('dialog[open]')) openCommand() } else if ((e.ctrlKey || e.metaKey) && e.key === 'Enter' && !$('dialog[open]')) { e.preventDefault(); openEntity('task') } else if (e.key === 'Escape') { $('#sidebar').classList.remove('open'); $('#mobile-menu').setAttribute('aria-expanded', 'false') } else if (!typing && e.key === '/' && !$('dialog[open]')) { e.preventDefault(); openCommand() } });
